function topFrequencyTotal(nums: number[]): number {
  const count = new Map<number, number>();
  for (const v of nums) count.set(v, (count.get(v) ?? 0) + 1);
  let top = 0;
  for (const c of count.values()) top = Math.max(top, c);
  let total = 0;
  for (const c of count.values()) if (c === top) total += c;
  return total;
}

