  const count = new Map<number, number>();
  let best = 0, total = 0;
  for (const v of nums) {
    const c = (count.get(v) ?? 0) + 1;
    count.set(v, c);
    if (c > best) { best = c; total = c; }
    else if (c === best) total += c;
